arguments.new_str:
void ApplyMigrations(AppDbContext db)
{
    // EF Core 9 manages its own transactions during Migrate();
    // wrapping it in a user transaction now throws.
    var strategy = db.Database.CreateExecutionStrategy();
    strategy.Execute(() =>
    {
        db.Database.Migrate();
    });
}

