using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — fixes for EF Core 9 breaking changes.
class CosmosContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 renamed the default discriminator
        // property from "Discriminator" to "$type".
        // Existing documents already store "Discriminator", so pin the
        // old name to avoid a data mismatch.
        modelBuilder.Entity<Product>()
            .HasDiscriminator<string>("Discriminator");
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Breaking change: EF Core 9 Cosmos provider removed synchronous query
// support. All queries must use async methods.
//
// BEFORE (throws InvalidOperationException in EF Core 9):
//   var items = db.Products.ToList();
//   var item  = db.Products.First();
//
// AFTER:
//   var items = await db.Products.ToListAsync();
//   var item  = await db.Products.FirstAsync();

